-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Emote("blinks at you a few times then speaks in a strangely musical, draconic voice. 'You vish to azzizt ze count of ze Tunarean Faerie Dragons?")
  elseif e.message:findi("assist") then
    e.self:Say("I vish to ztop ze Kromzek Foreman from continuing ta deztroy thiz land. Iv you vish to azzizt you can zlay ze Foreman and bring me hiz helm az proof.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 24873 }) then
    e.self:Say("Yeez hav eernd ta reezpect ov my peoplez, here iz ze crezt ov ze faerie dragons")
    e.other:SummonItem(24868)
    e.other:Faction(449, 30, 0)
    e.other:AddEXP(100)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
